def semver_sort(versions):
    def parse_version(v):
        # Split off build metadata
        if '+' in v:
            v, build = v.split('+', 1)
        else:
            build = ''

        # Split off pre-release
        if '-' in v:
            base, prerelease = v.split('-', 1)
        else:
            base = v
            prerelease = None

        # Parse base version
        parts = base.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease is not None:
            prerelease_parts = prerelease.split('.')
            # Convert to comparable form
            prerelease_comparable = []
            for part in prerelease_parts:
                if part.isdigit():
                    prerelease_comparable.append((0, int(part)))
                else:
                    prerelease_comparable.append((1, part))
        else:
            prerelease_comparable = None

        return (major, minor, patch, prerelease_comparable)

    def version_key(v):
        major, minor, patch, prerelease_comparable = parse_version(v)

        # For sorting: version without prerelease sorts after version with prerelease
        # So we use (major, minor, patch, has_prerelease_flag, prerelease_comparable)
        # where has_prerelease_flag is 1 if no prerelease (sorts later), 0 if has prerelease

        if prerelease_comparable is None:
            return (major, minor, patch, 1)
        else:
            return (major, minor, patch, 0, prerelease_comparable)

    # Use stable sort to maintain input order for equal precedence
    indexed_versions = [(v, i) for i, v in enumerate(versions)]
    sorted_versions = sorted(indexed_versions, key=lambda x: (version_key(x[0]), x[1]))

    return [v for v, _ in sorted_versions]

